diff --git a/io/io.cpp b/io/io.cpp
index 50ed8f0..fa474bf 100644
--- a/io/io.cpp
+++ b/io/io.cpp
@@ -416,6 +416,42 @@ extern "C" int c_bufcache_status(natl *blocks, natl *io_count)
 //   ESAME 2023-01-11 )

 // ( SOLUZIONE 2023-01-11
+buf_des* bufcache_find(des_ata* d, natl block)
+{
+	for (int i = 0; i < MAX_BUF_DES; i++) {
+		if (d->bufcache[i].full && d->bufcache[i].block == block)
+			return &d->bufcache[i];
+	}
+	return nullptr;
+}
+
+buf_des* bufcache_ensure(des_ata* d, natl block)
+{
+	buf_des *b;
+	for (int i = 0; i < MAX_BUF_DES; i++) {
+		if (!d->bufcache[i].full) {
+			b = &d->bufcache[i];
+			b->block = block;
+			b->full = true;
+			b->next = -1;
+			b->prev = -1;
+			return b;
+		}
+	}
+	b = &d->bufcache[d->lru];
+	if (b->next >= 0)
+		d->bufcache[b->next].prev = b->prev;
+	else
+		d->mru = b->prev;
+	if (b->prev >= 0)
+		d->bufcache[b->prev].next = b->next;
+	else
+		d->lru = b->next;
+	b->block = block;
+	b->next = -1;
+	b->prev = -1;
+	return b;
+}
 //   SOLUZIONE 2023-01-11 )
 /// Piedino dell'APIC per le richieste di interruzione dell'hard disk
 const natb HD_IRQ = 14;
@@ -495,6 +531,21 @@ extern "C" void c_readhd_n(natb vetti[], natl primo, natb quanti)

 /// @todo Gestire l'operazione tenendo conto della buffer cache.
 // ( SOLUZIONE 2023-01-11
+	sem_wait(d->mutex);
+	for (natb i = 0; i < quanti; i++) {
+		buf_des *b = bufcache_find(d, primo + i);
+		if (b) {
+			bufcache_promote(b);
+			memcpy(vetti + i * DIM_BLOCK, b->buf, DIM_BLOCK);
+		} else {
+			b = bufcache_ensure(d, primo + i);
+			starthd_in(d, vetti + i * DIM_BLOCK, primo + i, 1);
+			sem_wait(d->sincr);
+			memcpy(b->buf, vetti + i * DIM_BLOCK, DIM_BLOCK);
+			bufcache_promote(b);
+		}
+	}
+	sem_signal(d->mutex);
 //   SOLUZIONE 2023-01-11 )
 //   ESAME 2023-01-11 ]
 }
@@ -543,6 +594,20 @@ extern "C" void c_writehd_n(natb vetto[], natl primo, natb quanti)
 	//sem_signal(d->mutex);
 /// @todo Gestire l'operazione tenendo conto della buffer cache.
 // ( SOLUZIONE 2023-01-11
+	sem_wait(d->mutex);
+	for (natb i = 0; i < quanti; i++) {
+		buf_des *b = bufcache_find(d, primo + i);
+		if (b) {
+			memcpy(b->buf, vetto + i * DIM_BLOCK, DIM_BLOCK);
+			starthd_out(d, b->buf, primo + i, 1);
+			sem_wait(d->sincr);
+			bufcache_promote(b);
+		} else {
+			starthd_out(d, vetto + i * DIM_BLOCK, primo + i, 1);
+			sem_wait(d->sincr);
+		}
+	}
+	sem_signal(d->mutex);
 //   SOLUZIONE 2023-01-11 )
 //   ESAME 2023-01-11 ]
 }
@@ -735,6 +800,14 @@ bool hd_init()
 	hd::enable_intr();

 // ( SOLUZIONE 2023-01-11
+	d->lru = -1;
+	d->mru = -1;
+	d->io_count = 0;
+	for (int i = 0; i < MAX_BUF_DES; i++) {
+		d->bufcache[i].full = false;
+		d->bufcache[i].next = -1;
+		d->bufcache[i].prev = -1;
+	}
 //   SOLUZIONE 2023-01-11 )

 	return true;
